(window.webpackJsonp=window.webpackJsonp||[]).push([[112],{483:function(e,t,l){"use strict";l.r(t);var o=l(11),r=Object(o.a)({},(function(){var e=this,t=e._self._c;return t("ContentSlotsDistributor",{attrs:{"slot-key":e.$parent.slotKey}},[t("p",[e._v("《蛤蟆先生去看心理医生》是一本非常生动的书，每个动物都有自己鲜明的特征和个性，以蛤蟆的视角追溯了蛤蟆童年以及成年以后的经历。")]),e._v(" "),t("p",[e._v("读完这本书心里感到轻快，蛤蟆的角色代表了很多有心理困扰的人，书中涵盖了儿童自我状态、父母自我状态以及成人自我状态。强调了儿童基本情感、顺从状态、儿童如何释放愤怒、生命初始探索的两个问题、人生坐标、自证预言、高情商以及共情。")]),e._v(" "),t("p",[e._v("解释了环境对人生坐标的影响、以及成年以后如何打破依赖成长为成人自我状态。")]),e._v(" "),t("p",[e._v("看这本书学到了很多、思考了一些自身问题。对比了本我自我超我，本自具足以及一些极端心理问题")]),e._v(" "),t("h2",{attrs:{id:"阅读笔记"}},[t("a",{staticClass:"header-anchor",attrs:{href:"#阅读笔记"}},[e._v("#")]),e._v(" 阅读笔记")]),e._v(" "),t("Timeline",{attrs:{items:[{date:"2026年11月13日",title:"第一次咨询",desc:"必须完成的事情，唯有靠自己才能完成",color:"purple"},{date:"2026年11月13日",title:"第二次咨询",desc:"儿童自我状态——行为和感受都像一个孩子",color:"blue"},{date:"2026年11月13日",title:"第三次咨询",desc:"①儿童自我状态是由我们童年残留的遗迹搭建而成，包含我们小时候体验过的所有情感。你一定知道在刚出生时，我们只具备几种最基本的情感。幼年时，这些基本情感逐渐发展演变成更微妙、更复杂的行为模式，这些行为模式成为自我的核心，融为我们自身的一部分，定义了我们一生的行为。正因为这样，某些特定的情形和场景会激发我们的基本行为模式，让我们自动做出反应，所以我们会和小时候一样去行动和感受。②基本情感——快乐、深情、愤怒、悲伤、恐惧     所有这些情感加起来构成“自然型儿童”  这是整个儿童自我状态的重要组成部分。③父母对孩子意识产生的影响深远，面对哭闹的婴儿，母亲通常的反应是给予爱和安抚，但也有父母会做出缺乏爱心的举动，母亲可能累了，甚至病了，就会表现的很严厉。又或者，父亲的育儿观念可能非常严苛，就会故意无视婴儿的哭闹，怕“宠坏”了他。④父母其实拥有巨大的权利，可以对子女拥有绝对控制权。他们可以爱孩子也可以抛弃孩子，可以宠爱孩子也可以虐待孩子。⑤大多数父母会尽最大努力来养育孩子，很少有父母要故意伤害自己的孩子。可是父母也是人，会不可避免的把他们的观念和行为传递给后代，正如他们一定会把自己的基因传递给下一代一样，所以孩子们要学会的事，如何应对和防御因此产生的后果。⑥婴儿不能用逻辑或有意识的去想明白这些问题，但他们会从经验中学习，这样的学习不仅涉及用头脑思考，也涉及全部的自我，我们学到的是一种生存策略，并发展出一套行为来应对父母和其他人。幸运的话，我们就能用余下足够的精力来享受生活，这意味着每个婴儿都必须学习如何调整他的基本行为，来应对自己所处的初始状况。这些调整就像原子核一样，以后我们所有的行为都围绕着这个核心形成和发展，当然，人生后面阶段的许多其他事件也会对我们造成影响，但这些最早期的经历塑造了人格的雏形，所以我们无法否认也无法忘记它们。⑦本我所在，自我相依。 --弗洛伊德⑧这些调整的过程形成了适应型儿童，儿童自我状态包含了：自然型儿童和适应型儿童。",color:"purple"},{date:"2026年11月13日",title:"第四次咨询",desc:"①问：倘若一个人被比自己强大许多倍还无法逃离的人欺凌和伤害，他可能做出什么反应？答：如果这个人确实没有力量，就必须学习顺从压迫者，不然可能无法生活下去。问：正式这样。所以你还是个孩子时，是不是也一样得学习如何顺从父母严苛的要求和心愿？答：我猜，如果你被迫顺从某个人，就意味着你不与他争辩。你照他说的去做，而且同意他的想法。除了顺从我父母的意愿之外，我还总是想要取悦他们。我不确定自己有没有成功过，但我记得很清楚，我想让他们对我满意，为我骄傲。还有道歉习惯性道歉来安抚父母，也是顺从的一种。②依赖：对大多数人而言，成长的本质就是要减少并最终打破这样的依赖关系，这样才能成为一个独立自主的人。很少有人能完全达成这点，有些人能部分达成，而很多人则会依赖一辈子。③依赖和顺从的关系：顺从行为可能导致有些人学会了把依赖当成生活方式。换句话说，这些人永远都没有真正长大成人。④顺从行为：同意、取悦、道歉、依赖",color:"blue"},{date:"2026年11月13日",title:"第五次咨询",desc:"①问：对责备或者对不善的言语感到悲伤内疚，自我攻击恐惧，而不是愤怒是为什么呢？答：仁慈的独裁者也就是你的父母，完全掌控你，同时又对你倍加关心和照顾，你完全依赖他们，你怎么会对他们生气呢？何况你还爱着他们。问：如果我的愤怒真的遇到了我父母的绝对权利，会发生什么呢？你得学习如何不带攻击性的发火。（我会变得委屈看起来很可怜会哭原来是不带攻击性的发火，是因为愤怒被降级了。②用缓和的方式释放愤怒，让别人几乎察觉不到，这样就不会让任何人不安。例如：撒泼耍性子是表达愤怒的一种幼稚的方式。就像孩子听到大人说“不行，你不能这样！”让孩子非常愤怒，同时又感到无助，因为对那个让他生气的大人，孩子没法用暴力或者带有攻击性的行为去回应，所以唯一能做的就是躺倒在地，又踢又叫。而当成年人也这么干的时候，我们会说他在“无理取闹”。③问：你说过不带攻击性地释放愤怒是需要一段时间的，可是撒泼也持续不了多久啊。答：是这样，不过有些方式可以持续很久，几个小时甚至好几天。比方说怄气。④怄气：怄气的人总是绷着脸，阴沉沉的样子，而且安静得很反常。在我看来适应型儿童的所有行为里，怄气是最能说明怎样用时间来稀释愤怒的例子。通常这是孩子在权威之下无法随心所欲才做出的反应。成年人或许会因为输掉一场权利斗争而生闷气，也是同样道理。说白了，怄气是输家在对强大的赢家做出反应，这个行为完成了我们刚才讨论的，所谓通过逐步少量降压来降低愤怒的强度，这样攻击性肯定也就减弱了。⑤儿童如何释放愤怒（从左往右从强到弱）：叛逆、撒泼、怄气、任性、郁闷、拖延、厌烦、退缩。所有这些行为策略实际上都是我们童年发展而来的防御机制，用来保护我们免于受到伤害。这危害可能是真实存在的，也可能是想像出来的。当成年人怄气、撒泼、郁闷或是厌烦的时候，我们会想他们究竟是行为不当，还是在无意识或者无法控制地重演童年的行为模式。",color:"purple"},{date:"2026年11月13日",title:"第六次咨询",desc:"①联合他人欺负自己，偷偷地或无意识地配合对方，来给自己制造不快。②一些心理概念，会让人感到害怕，不合逻辑，愚蠢。但是越能帮助你深入自我的概念，也越容易引发激烈的阻抗，因为这些概念最容易打破我们的心理平衡，最有可能带你走向深层的蜕变，这个过程往往是痛苦的。我们看到的自己，并不一定总是我们喜欢的样子。当下的你，从变成你想成为的自己，必定要经历行为和态度的转变，需要付出艰辛的努力，需要勇气和决心。③父母自我状态：包含从出生起，我们从父母那里学到的所有价值观和道德观，还包含了对生活的评判标准，让我们借此判断是非对错。这些价值观来自父母，所以父母是最能左右我们行为的人。他们的言行塑造了我们童年的生活，也不可避免地对我们之后的人生产生影响。④挑剔型父母：爱批评、严肃、愤怒。控制型父母（批判型）：喜欢指责、挑剔、定规矩。养育型父母（照顾型）：温柔、安慰、允许。⑤每个人都有父母自我状态，来自年幼时父母的言行和对待我们的方式。⑥没有一种批判比自我批判更强烈。有的父母自我状态用来批判别人，有的父母自我状态用来批判自己。",color:"blue"},{date:"2026年11月13日",title:"第七次咨询",desc:"①成人自我状态：既不表现得像父母，也不会觉得像孩子。更像个大人，更像当下的自己。指我们用理性而不是情绪化的方式来行事。它让我们能应对此时此地正在发生的现实状况。在这个状态下，我们能计划、考虑、决定、行动，我们能理性而合理的行事。处于这个状态时，我们所有的知识和技能都能为自己所用，而不再被脑子里父母过去的声音所驱使，也不会被童年的情绪所围困。相反，我们能思考当下的状况，基于事实来决定怎么做。②人是自己选择情绪的，要为自己的情绪负责。（类似于处在成人自我状态时，我们会基于事实思考冲突带给自己的影响，我想要建立什么样的边界，想要什么样的对待方式，坚定反对侵害边界的情况）（否则容易陷入情绪里）",color:"purple"},{date:"2026年11月13日",title:"第八次咨询",desc:"讲故事",color:"blue"},{date:"2026年11月13日",title:"第九次咨询",desc:"①早期经历塑造人对世界的感受1-5岁，童年时我们试图回答两个问题。第一个：我是怎么看自己的？我好吗？  第二个问题：我是怎么看别人的？他们好吗？生命本身，特别是自己体验到的生命会让人去探究这两个问题。②组成了以下四种答案：1.我好；你也好。2.我好；你不好。3.我不好；你好。4.我不好；你也不好。③自证预言：一旦我们在童年决定用哪种态度和观点，我们就会在随后的人生里始终坚持自己的选择。这些态度和观点，变成我们的底层架构。从那以后，我们便构建出一个世界，不断确认和支持这些信念和预期。换一个词来说，我们把自己的人生变成了一个自证预言",color:"blue"},{date:"2026年11月13日",title:"第十次咨询",desc:"反问，问状态，却不评价这个人",color:"blue"},{date:"2026年11月13日",title:"第十一次咨询",desc:"①高情商：有强大的自我意识，了解自己的情感。他们能管理情绪，能从悲伤和不幸中重新振作。但也许最重要的是，他们能控制冲动，也懂得延迟满足，从而避免轻率的决定和不妥的行为。②高情商还包括共情。情感智力能让你在自我成长和完善的路上走得更远，因为它将带你从独立的个体走向共生的关系。③独立性隐含了做自己的自豪感，还包括独特的才能、与众不同的部分。独立的人时刻守护新发现的自主权，如同一个曾经被殖民的国家重获自由一样。这当然没错，但共生性则体现出成熟和自我接纳，还包括求同存异地接纳他人。共生性可以让你在社交和工作上与别人有效联结，协同合作。",color:"blue"}]}})],1)}),[],!1,null,null,null);t.default=r.exports}}]);